'use client'

import type { ChartDatum, ComponentStates } from '@polymorph/react'
import { ScatterChart } from './ScatterChart'

/**
 * States fixture, from `design/components/scatter-chart.md`'s States table.
 *
 * The data is Relay's. It is generated by arithmetic, not randomly, so the
 * correlation is the same on every render.
 */

/**
 * One mark per agent (24): average handle minutes against CSAT, negatively
 * correlated with realistic scatter.
 */
const AGENTS: ChartDatum[] = Array.from({ length: 24 }, (_, index) => {
  const minutes = 2 + ((index * 7) % 12) + ((index * 13) % 10) / 10
  const wobble = (((index * 29) % 11) - 5) / 12
  return {
    minutes: Math.round(minutes * 10) / 10,
    csat: Math.round((5.1 - minutes * 0.14 + wobble) * 100) / 100,
  }
})

/** The same measures split by team. Each observation belongs to one series. */
const TEAMS: ChartDatum[] = AGENTS.map((row, index) =>
  index % 2 === 0
    ? { minutes: row['minutes'] ?? 0, triage: row['csat'] ?? 0, escalations: null }
    : { minutes: row['minutes'] ?? 0, triage: null, escalations: row['csat'] ?? 0 },
)

/** The third column for bubble mode: tickets handled, 20–160. */
const WITH_LOAD: ChartDatum[] = AGENTS.map((row, index) => ({
  ...row,
  tickets: 20 + ((index * 37) % 141),
}))

/** Four series, above the canonical cap of three, for the dev-warning entry. */
const FOUR_TEAMS: ChartDatum[] = AGENTS.map((row, index) => {
  const keys = ['triage', 'escalations', 'billing', 'onboarding']
  const mine = keys[index % 4] ?? 'triage'
  return {
    minutes: row['minutes'] ?? 0,
    ...Object.fromEntries(keys.map((key) => [key, key === mine ? row['csat'] : null])),
  }
})

/** A dense plot within the linear scan's intended range: 500 observations, one series. */
const DENSE: ChartDatum[] = Array.from({ length: 500 }, (_, index) => {
  const minutes = 1 + ((index * 17) % 130) / 10
  const wobble = (((index * 31) % 23) - 11) / 14
  return {
    minutes: Math.round(minutes * 10) / 10,
    csat: Math.round((5.2 - minutes * 0.12 + wobble) * 100) / 100,
  }
})

/** Deploys across July: date against minutes of incident that followed. */
const DEPLOYS: ChartDatum[] = Array.from({ length: 18 }, (_, index) => ({
  date: `2026-07-${String(1 + ((index * 5) % 28)).padStart(2, '0')}`,
  minutes: ((index * 43) % 90) + 4,
}))

const CSAT_SERIES = [{ key: 'csat', label: 'CSAT' }] as const

export const states: ComponentStates = {
  component: 'ScatterChart',

  entries: [
    {
      name: 'handle time vs CSAT',
      render: () => (
        <ScatterChart
          data={AGENTS}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          label="Handle time against satisfaction"
        />
      ),
      expect: { 'data-size': 'md' },
    },
    {
      name: 'two teams',
      render: () => (
        <ScatterChart
          data={TEAMS}
          series={[
            { key: 'triage', label: 'Triage' },
            { key: 'escalations', label: 'Escalations' },
          ]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          label="Handle time against satisfaction, by team"
        />
      ),
    },
    {
      // Shows the sqrt scale between the 8px and 24px bounds. Area encodes the
      // load, so twice the tickets gives twice the area, not twice the width.
      name: 'bubble',
      render: () => (
        <ScatterChart
          data={WITH_LOAD}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          bubble={{ key: 'tickets', label: 'Tickets handled' }}
          label="Handle time, satisfaction and load"
        />
      ),
    },
    {
      // Expect the dev warning naming --pm-chart-cap and the any-neighbour
      // cap. The plot still draws every series.
      name: 'cap warning',
      render: () => (
        <ScatterChart
          data={FOUR_TEAMS}
          series={[
            { key: 'triage', label: 'Triage' },
            { key: 'escalations', label: 'Escalations' },
            { key: 'billing', label: 'Billing' },
            { key: 'onboarding', label: 'Onboarding' },
          ]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          label="Four teams — past the cap"
        />
      ),
    },
    {
      // The linear scan's intended range. Marks stay 8px and the twin holds
      // every row.
      name: 'dense',
      render: () => (
        <ScatterChart
          data={DENSE}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          label="Every conversation this quarter"
        />
      ),
    },
    {
      name: 'time x',
      render: () => (
        <ScatterChart
          data={DEPLOYS}
          series={[{ key: 'minutes', label: 'Incident minutes' }]}
          x={{ key: 'date', scale: 'time', label: 'Deploy date' }}
          label="Deploys against incident minutes"
        />
      ),
    },
    {
      name: 'annotations',
      render: () => (
        <ScatterChart
          data={AGENTS}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          annotations={[
            { kind: 'band', from: 4.5, to: 5, label: 'CSAT target' },
            { kind: 'line', value: 4, label: 'Floor' },
          ]}
          label="Handle time against satisfaction, with the target zone"
        />
      ),
    },
    {
      name: 'empty',
      render: () => (
        <ScatterChart
          data={[]}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes' }}
          label="Handle time against satisfaction"
        />
      ),
      expect: { 'data-state': 'empty' },
    },
    {
      name: 'loading',
      render: () => (
        <ScatterChart
          data={AGENTS}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes' }}
          loading
          label="Handle time against satisfaction"
        />
      ),
      expect: { 'data-state': 'loading' },
    },
    {
      // `false` removes the visual layer only: the keyboard reading position,
      // its announcements and the table twin all stay.
      name: 'tooltip off',
      render: () => (
        <ScatterChart
          data={AGENTS}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes' }}
          tooltip={false}
          label="Handle time against satisfaction, print"
        />
      ),
    },
    {
      // With `onSelect`: the summary names the activation, and an agent can pick a point.
      name: 'selectable',
      render: () => (
        <ScatterChart
          data={AGENTS}
          series={[...CSAT_SERIES]}
          x={{ key: 'minutes', label: 'Handle minutes' }}
          label="Handle time against satisfaction"
          onSelect={() => {}}
        />
      ),
    },
  ],

  /*
   * `[aria-pressed='false']` is a hidden series' legend key. Its paint lives in
   * the legend's sheet, which joins this member's `composes` closure so the
   * selectors law can see it (see the spec's note).
   */
  requiredSelectors: [
    "[data-state='empty']",
    "[data-state='loading']",
    '[data-active]',
    "[aria-pressed='false']",
    ':focus-visible',
  ],
}
